class TextEditor {
  private s = "";
  private pos = 0;

  addText(text: string): void {
    this.s = this.s.slice(0, this.pos) + text + this.s.slice(this.pos);
    this.pos += text.length;
  }

  deleteText(k: number): number {
    const d = Math.min(k, this.pos);
    this.s = this.s.slice(0, this.pos - d) + this.s.slice(this.pos);
    this.pos -= d;
    return d;
  }

  private tail(): string {
    return this.s.slice(Math.max(0, this.pos - 10), this.pos);
  }

  cursorLeft(k: number): string {
    this.pos = Math.max(0, this.pos - k);
    return this.tail();
  }

  cursorRight(k: number): string {
    this.pos = Math.min(this.s.length, this.pos + k);
    return this.tail();
  }
}

