class TextEditor {
  private left: string[] = [];
  private right: string[] = []; // reversed: top is the char right after the cursor

  addText(text: string): void {
    for (const ch of text) this.left.push(ch);
  }

  deleteText(k: number): number {
    const d = Math.min(k, this.left.length);
    this.left.length -= d;
    return d;
  }

  private tail(): string {
    return this.left.slice(Math.max(0, this.left.length - 10)).join("");
  }

  cursorLeft(k: number): string {
    for (let i = 0; i < k && this.left.length; i++) this.right.push(this.left.pop()!);
    return this.tail();
  }

  cursorRight(k: number): string {
    for (let i = 0; i < k && this.right.length; i++) this.left.push(this.right.pop()!);
    return this.tail();
  }
}

